package com.aistock.prediction.portfolioquestion;
import com.aistock.common.BusinessException;import com.aistock.prediction.portfolioanalysis.PortfolioRepository;import com.aistock.prediction.explanation.MaasClient;import com.fasterxml.jackson.databind.*;import org.springframework.dao.DataAccessException;import org.springframework.http.HttpStatus;import java.time.Clock;import java.util.*;import java.util.function.Supplier;import static com.aistock.prediction.portfolioquestion.PortfolioQuestionRecords.*;
public final class PortfolioQuestionService {
 private final PortfolioQuestionRepository records;private final PortfolioRepository source;private final MaasClient client;private final ObjectMapper mapper;private final Clock clock;private final boolean enabled;private final int maxFacts,maxBytes,maxPrompt;private final PortfolioRuleService rules;
 public PortfolioQuestionService(PortfolioQuestionRepository records,PortfolioRepository source,MaasClient client,ObjectMapper mapper,Clock clock,boolean enabled,int maxFacts,int maxBytes,int maxPrompt){this.records=records;this.source=source;this.client=client;this.mapper=mapper;this.clock=clock;this.enabled=enabled;this.maxFacts=maxFacts;this.maxBytes=maxBytes;this.maxPrompt=maxPrompt;rules=new PortfolioRuleService(source,mapper);if(maxFacts<1||maxFacts>1800||maxBytes<1||maxBytes>98304||maxPrompt<1||maxPrompt>65536)throw new IllegalArgumentException("Invalid portfolio question capacity");}
 public boolean configured(){return enabled&&client.enabled();}
 public Receipt generate(UUID owner,Request input){return database(()->generateOwned(owner,input));}
 private Receipt generateOwned(UUID owner,Request input){if(owner==null||input==null||input.operationId()==null||input.analysisId()==null)throw PortfolioQuestionInput.invalid();var in=new Request(input.operationId(),input.analysisId(),PortfolioQuestionInput.normalize(input.question()),input.disclosureAccepted());var prior=records.replay(owner,in,clock);if(prior!=null)return prior;var saved=source.get(owner,in.analysisId());if(!in.disclosureAccepted())throw new BusinessException("AI_DISCLOSURE_REQUIRED","请先确认本次持仓信息用于云端解释",HttpStatus.FORBIDDEN);if(!configured())throw new BusinessException("AI_NOT_CONFIGURED","持仓AI问答尚未启用，规则说明和原估值仍可查看",HttpStatus.SERVICE_UNAVAILABLE);var facts=PortfolioQuestionFacts.build(saved,in.question(),client.model(),mapper,maxFacts,maxBytes);PortfolioQuestionPrompt.checkBudget(in.question(),facts.values(),mapper,maxPrompt);var claim=records.claim(owner,in,facts,clock);if(!claim.execute())return claim.receipt();Answer answer=null;String error=null;try{answer=PortfolioAnswerTemplate.render(client.generatePortfolioQuestion(in.question(),facts.values()),facts,mapper);}catch(BusinessException e){error=e.code();}catch(RuntimeException e){error="AI_UNAVAILABLE";}return records.complete(owner,in.operationId(),answer,error,clock);}
 public JsonNode rules(UUID owner,UUID analysis,String topic){return database(()->rules.describe(owner,analysis,topic));}
 public JsonNode get(UUID owner,UUID answer){return database(()->records.get(owner,answer));}
 public Receipt operation(UUID owner,UUID op){return database(()->records.operation(owner,op,clock));}
 public Page list(UUID owner,UUID analysis,String before,String upper){return database(()->records.list(owner,analysis,before,upper,configured(),clock));}
 private <T>T database(Supplier<T> action){try{return action.get();}catch(DataAccessException e){throw new BusinessException("AI_STORAGE_UNAVAILABLE","问答记录服务暂不可用，请先查询原请求，原估值和已有回答保留",HttpStatus.SERVICE_UNAVAILABLE);}}
}
